import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.DToEn73J.js";const d=JSON.parse('{"title":"预算控制","description":"","frontmatter":{"title":"预算控制","chapter":"1.4","order":4,"summary":"预算控制以 max_steps、token/cost 护栏与重复检测防止 Agent Loop 失控与烧钱。"},"headers":[],"relativePath":"01-agent-basics/budget-control.md","filePath":"01-agent-basics/budget-control.md","lastUpdated":1787724133000}'),l={name:"01-agent-basics/budget-control.md"};function o(i,a,r,p,c,h){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="预算控制" tabindex="-1">预算控制 <a class="header-anchor" href="#预算控制" aria-label="Permalink to &quot;预算控制&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>预算控制是在 Agent Loop 外设的硬约束，防止任务因死循环、模型抖动或恶意输入无限消耗资源。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p>三层护栏叠加：</p><ol><li><strong>步数上限 max_steps</strong>：loop 累计轮次超阈即终止，返回部分结果。</li><li><strong>token/cost budget</strong>：按请求累计 prompt+completion tokens，逼近预算时提前停止并告警。</li><li><strong>超时与死循环检测</strong>：单步超时 kill；用滑动窗口检测「重复 tool_calls 序列」或「输出几乎不变」，判定 stuck 后触发 Kill Switch（/05-safety-governance/kill-switch）。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>guard(step_count, token_used, elapsed, last_calls):</span></span>
<span class="line"><span>  if step_count   &gt; MAX_STEPS:        return STOP(&quot;step&quot;)</span></span>
<span class="line"><span>  if token_used   &gt; TOKEN_BUDGET:     return STOP(&quot;budget&quot;)</span></span>
<span class="line"><span>  if elapsed      &gt; TIMEOUT:          return STOP(&quot;timeout&quot;)</span></span>
<span class="line"><span>  if repeats(last_calls, WINDOW):     return STOP(&quot;loop&quot;)</span></span>
<span class="line"><span>  return CONTINUE</span></span></code></pre></div><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>不做预算，一个 prompt injection 诱导的循环或模型 bug 可在数分钟内烧掉巨额调用费，且占用并发槽拖垮其它任务。护栏是 Agent 上生产的最低门槛。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>只设 max_steps 不设 cost budget，长上下文单步 token 暴涨仍会超额。</li><li>重复检测只看相同输入，忽略「换表述但同效果」的软循环。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li>OpenAI Agents SDK：max_turns 限制轮次；Guardrails 可拦截。<a href="https://openai.github.io/openai-agents-python/ref/agents/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/ref/agents/</a></li><li>LangGraph：checkpointer + interrupt 支持在预算点人工/自动暂停。<a href="https://langchain-ai.github.io/langgraph/" target="_blank" rel="noreferrer">https://langchain-ai.github.io/langgraph/</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>/01-agent-basics/agent-loop</li><li>/01-agent-basics/concurrency</li><li>/05-safety-governance/kill-switch</li><li>/06-engineering-ops/cost-latency</li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>`,17)])])}const g=t(l,[["render",o]]);export{d as __pageData,g as default};
